insert into kb.chunks (chunk_id,document_version_id,ordinal,heading_path,content,token_count,content_sha256,language,verification_status,access_scope,active,metadata) values ('LP-WEB-LEGACY-14-DOC-CH-001',(select dv.id from kb.document_versions dv join kb.documents d on d.id=dv.document_id where d.document_id='LP-WEB-LEGACY-14-DOC' and dv.version='2025-10-20-export'),0,'Organizational Design Errors: Structuring a Business Around People Instead of Organizational Needs','Archive source LP-WEB-LEGACY-14. Organizational Design Errors: Structuring a Business Around People Instead of Organizational Needs. Legacy Squarespace/WordPress export record (post; status publish). Historical path: /views-thinking-by-alex-lawton/marketing/siloes-gb7b3

