insert into kb.chunks (chunk_id,document_version_id,ordinal,heading_path,content,token_count,content_sha256,language,verification_status,access_scope,active,metadata) values ('LP-WEB-LIVE-ES-ABOUT-DOC-CH-001',(select dv.id from kb.document_versions dv join kb.documents d on d.id=dv.document_id where d.document_id='LP-WEB-LIVE-ES-ABOUT-DOC' and dv.version='2026-08-05-capture'),0,'Nosotros | Agencia Medios Innovadora Madrid, Barcelona, Asturias — LA PIPA','Archive source LP-WEB-LIVE-ES-ABOUT. Nosotros | Agencia Medios Innovadora Madrid, Barcelona, Asturias — LA PIPA. Captured public page: https://www.lapipa.io/es/about

